"""Exact linearized (pre-scrambling) quantum state of the thermalizing field: the Gaussian state generated by the classical
tangent map S(z) of the GRIN resonant model, V(z) = S S^T / 2 in quadratures (x, y) with vacuum variance 1/2.
Reports, at checkpoints:
  - multimode squeezing lambda_min(V) = 1/(2 sigma_max(S)^2) (exact via symplecticity) and anti-squeezing;
  - photon-counting-accessible bound lambda_gen = 2 lambda_min(V_amp) (amplitude quadratures at the local mean phases);
  - Fano factors of N_total and E' (conserved);
  - per-mode: entanglement entropy S_p, purity, minimum quadrature variance (single-mode squeezing), Fano factor F_p.
"""
import numpy as np, json, sys, time, warnings
warnings.filterwarnings('ignore')
import grin_model as gm

def run(K=5, Eprime=0.6, sigma=0.3, zmax=400., dz=0.02, checkpoints=(1, 2, 5, 10, 20, 50, 100, 200, 300, 400),
        phase_seed=1, dis_seed=7):
    groups, eps, _, S4, R = gm.build(K, 0, 0)
    M = len(groups); R2 = R.reshape(M, -1); RR = R.reshape(M*M, M*M)
    rng = np.random.default_rng(phase_seed)
    I0 = np.zeros(M); a = Eprime/3.; i1 = groups==1; i2 = groups==2
    I0[i1] = a/i1.sum(); I0[i2] = a/i2.sum(); I0[0] = 1-I0.sum()
    A = np.sqrt(I0)*np.exp(1j*rng.uniform(0, 2*np.pi, M))
    Smat = np.eye(2*M)
    drng = np.random.default_rng(dis_seed)
    blocks = [np.where(groups==k)[0] for k in range(K) if np.sum(groups==k) > 1]
    def fA(A):
        v = np.multiply.outer(np.multiply.outer(A.conj(), A), A).reshape(-1)
        return 1j*(R2 @ v)
    def Lmat(A):
        P = (RR @ np.outer(A, A).reshape(-1)).reshape(M, M)
        Q = 2*np.einsum('pqrs,q,r->ps', R, A.conj(), A, optimize=True)
        Qr, Qi, Pr, Pi = Q.real, Q.imag, P.real, P.imag
        return np.block([[-(Qi+Pi), -(Qr-Pr)], [(Qr+Pr), (Pi-Qi)]])
    def deriv(A, Sm):
        return fA(A), Lmat(A) @ Sm
    out = []; cps = sorted(checkpoints); ci = 0
    nsteps = int(round(zmax/dz))
    for n in range(1, nsteps+1):
        k1 = deriv(A, Smat); k2 = deriv(A+0.5*dz*k1[0], Smat+0.5*dz*k1[1])
        k3 = deriv(A+0.5*dz*k2[0], Smat+0.5*dz*k2[1]); k4 = deriv(A+dz*k3[0], Smat+dz*k3[1])
        A = A + dz*(k1[0]+2*k2[0]+2*k3[0]+k4[0])/6
        Smat = Smat + dz*(k1[1]+2*k2[1]+2*k3[1]+k4[1])/6
        if sigma > 0:
            for b in blocks:
                nb = len(b); Z = (drng.standard_normal((nb,nb)) + 1j*drng.standard_normal((nb,nb)))/2
                Hh = (Z + Z.conj().T)/np.sqrt(2); w_, V_ = np.linalg.eigh(Hh)
                U = (V_*np.exp(-1j*sigma*np.sqrt(dz)*w_)) @ V_.conj().T
                A[b] = U @ A[b]
                Ur, Ui = U.real, U.imag
                xb, yb = Smat[b, :].copy(), Smat[M+b, :].copy()
                Smat[b, :] = Ur @ xb - Ui @ yb; Smat[M+b, :] = Ui @ xb + Ur @ yb
        z = n*dz
        if ci < len(cps) and z >= cps[ci] - 1e-9:
            ci += 1
            sv = np.linalg.svd(Smat, compute_uv=False)
            V = Smat @ Smat.T/2
            I = np.abs(A)**2; ph = np.angle(A)
            Pa = np.zeros((M, 2*M)); Pa[np.arange(M), np.arange(M)] = np.cos(ph); Pa[np.arange(M), M+np.arange(M)] = np.sin(ph)
            Vamp = Pa @ V @ Pa.T
            lam_gen = 2*np.linalg.eigvalsh(Vamp)[0]
            # conserved quantities: total N and E' amplitude combinations, Fano relative to shot noise
            wN = np.sqrt(I); FN = 2*(wN @ Vamp @ wN)/np.sum(I)
            wE = eps*np.sqrt(I); FE = 2*(wE @ Vamp @ wE)/np.sum(eps**2*I) if np.sum(eps**2*I) > 0 else np.nan
            modes = []
            for p in [0] + [int(np.where(groups==k)[0][0]) for k in range(1, K)]:
                Vp = V[np.ix_([p, M+p], [p, M+p])]
                nu = np.sqrt(max(np.linalg.det(Vp), 0.25))
                Sent = (nu+0.5)*np.log(nu+0.5) - (nu-0.5)*np.log(nu-0.5) if nu > 0.5 + 1e-12 else 0.0
                modes.append(dict(p=p, group=int(groups[p]), I=float(I[p]), nu=float(nu), S_ent=float(Sent), purity=float(0.5/nu),
                                  min_quad_dB=float(10*np.log10(np.linalg.eigvalsh(Vp)[0]/0.5)), Fano=float(2*Vamp[p, p])))
            out.append(dict(z=z, log_sigma_max=float(np.log(sv[0])), log_sigma_min=float(np.log(sv[-1])),
                            multimode_min_quad_dB=float(10*np.log10(1/(2*sv[0]**2)/0.5)),
                            lambda_gen=float(lam_gen), lambda_gen_dB=float(10*np.log10(lam_gen)), Fano_N=float(FN), Fano_E=float(FE),
                            symplectic_check=float(np.max(np.abs(Smat.T @ np.block([[np.zeros((M,M)), np.eye(M)], [-np.eye(M), np.zeros((M,M))]]) @ Smat
                                                              - np.block([[np.zeros((M,M)), np.eye(M)], [-np.eye(M), np.zeros((M,M))]])))),
                            modes=modes))
    return dict(K=K, M=M, Eprime=Eprime, sigma=sigma, dz=dz, records=out)

if __name__ == '__main__':
    res = []
    t0 = time.time()
    for Ep in [0.3, 0.6, 0.9]:
        for sig in [0.3, 0.0]:
            o = run(Eprime=Ep, sigma=sig); res.append(o)
            r = o['records'][-1]
            print(f"E'={Ep} sigma={sig}: z={r['z']:.0f} lnsmax={r['log_sigma_max']:.2f} multimode_sq={r['multimode_min_quad_dB']:.1f} dB lam_gen={r['lambda_gen']:.3f} FN={r['Fano_N']:.3f} FE={r['Fano_E']:.3f} symp={r['symplectic_check']:.1e}", flush=True)
    json.dump(res, open('gauss_state.json', 'w'), indent=1); print('wall', time.time()-t0)
